#!/usr/bin/env python3
"""Consume saved 4B raw outputs in fixed native CMEE cases. No model or DB I/O."""
import argparse
from dataclasses import asdict, replace
from enum import Enum
import hashlib
import json
from pathlib import Path
import re
import subprocess
import sys

# Verifying a pinned API source must not dirty it with generated bytecode.
sys.dont_write_bytecode = True

from run_pilot import MODEL, REVISION, PROFILE, adapter_hashes, digest, read_jsonl, strict_json, validate_data, write_json

FIT_IDS = {"FIT-FT-CHAIR-INITIAL", "FIT-FT-CHAIR-AFTER-CORRECTION"}
SCOPE = ("Fixed-source, independent teacher-family fit cases. The correction uses its saved native prior; "
         "it is not a dynamic roundtrip from the actual initial model output, a service persistence test, "
         "a real GPU thread roundtrip, a user-device test, or product acceptance.")


def json_value(value):
    if isinstance(value, Enum):
        return value.value
    if hasattr(value, "__dataclass_fields__"):
        return {key: json_value(item) for key, item in asdict(value).items()}
    if isinstance(value, dict):
        return {key: json_value(item) for key, item in value.items()}
    if isinstance(value, (tuple, list)):
        return [json_value(item) for item in value]
    return value


def load_api(api_root, expected_commit):
    """CLI precondition: explicit, fixed API source; never fetch or modify it."""
    api_root = Path(api_root).resolve()
    if type(expected_commit) is not str or not re.fullmatch(r"[0-9a-f]{40}", expected_commit):
        raise ValueError("dataset_cmee_api_commit_not_fixed")
    actual = subprocess.run(["git", "-C", str(api_root), "rev-parse", "HEAD"], check=True,
                            capture_output=True, text=True).stdout.strip()
    if actual != expected_commit:
        raise ValueError("cmee_api_commit_mismatch")
    dirty = subprocess.run(["git", "-C", str(api_root), "status", "--porcelain", "--", "ai/services/ai_inference"],
                           check=True, capture_output=True, text=True).stdout
    if dirty.strip():
        raise ValueError("cmee_api_source_not_clean_at_fixed_commit")
    inference = api_root / "ai" / "services" / "ai_inference"
    if not inference.is_dir():
        raise ValueError("api_root_missing_inference_package")
    sys.path.insert(0, str(inference))
    from cocolon_meaning_experience_engine import model_candidate_source
    if not Path(model_candidate_source.__file__).resolve().is_relative_to(inference):
        raise ValueError("another_api_package_already_loaded")
    return actual


def reconstruct_request(example):
    """Restore only the native_case supplied by the source-bound formal dataset."""
    from emlis_ai_current_input_bundle import build_emlis_current_input_bundle
    from cocolon_meaning_experience_engine.contracts import GenerationRequest
    from cocolon_meaning_experience_engine.source_kernel import freeze_text_source
    from cocolon_meaning_experience_engine.emlis_thread_contracts import EmlisThreadInputV1, SupplementalAnswerSource
    from cocolon_meaning_experience_engine.emlis_semantic_admission import _control
    case = example["native_case"]
    if set(case) != {"original", "request_id", "thread_id", "capability_snapshot", "question_control", "answers",
                     "current_round", "prior_snapshot_json"}:
        raise ValueError("native_case_shape_invalid")
    original = case["original"]
    request = GenerationRequest(case["request_id"], build_emlis_current_input_bundle(original), original["id"])
    source = freeze_text_source(request)
    thread = EmlisThreadInputV1(case["thread_id"], source.envelope.envelope_id,
        answers=tuple(SupplementalAnswerSource(**row) for row in case["answers"]),
        current_round=case["current_round"], capability_snapshot=case["capability_snapshot"],
        question_control_context=_control(case["question_control"]))
    return replace(request, emlis_thread=thread), case["prior_snapshot_json"]


def consume_raw(example, raw_record, *, expected_adapter_revision):
    """Testable offline consumer. Caller sets sys.path to its explicit API checkout.

    The CLI separately enforces API commit and dataset hashes. This helper does
    not create a native answer or prior from any generated observation.
    """
    from cocolon_meaning_experience_engine import MeaningExperienceEngine
    from cocolon_meaning_experience_engine.model_candidate_source import build_model_messages
    from cocolon_meaning_experience_engine.preparation import prepare_emlis, receive_candidate
    from cocolon_meaning_experience_engine.emlis_semantic_admission import SemanticInput, SemanticNotAdopted
    result = {"case_id": raw_record.get("case_id"), "raw_record": raw_record, "scope": SCOPE,
              "identity_matches": False, "messages_match": False, "adoption": "NOT_ADOPTED",
              "receipt": None, "meaning_checkpoint": None, "semantic_snapshot": None,
              "outcome": None, "body": None, "question": None}
    try:
        if raw_record.get("case_id") != "FIT-" + example["id"] or raw_record.get("case_id") not in FIT_IDS:
            result.update(status="RAW_CASE_ID_MISMATCH", reason_code="raw_not_bound_to_this_chair_case")
            return result
        request, prior = reconstruct_request(example)
        # build_model_messages revalidates the actual prior via model_prior_for_messages.
        messages = build_model_messages(request, prior)
        result["messages_match"] = messages == example["messages"][:-1]
        if not result["messages_match"]:
            result.update(status="INPUT_MESSAGES_MISMATCH", reason_code="dataset_runtime_projection_mismatch")
            return result
        material = prepare_emlis(request)
        result["request_ref"] = material.request_id
        result["identity_matches"] = (raw_record.get("model") == MODEL and raw_record.get("revision") == REVISION
            and raw_record.get("adapter_revision") == expected_adapter_revision)
        usage = raw_record.get("usage")
        if "usage" not in raw_record:
            usage = {key: raw_record[key] for key in ("input_tokens", "output_tokens") if key in raw_record} or None
        receipt = receive_candidate(material, request_id=material.request_id,
            raw_output=raw_record.get("raw_text"), finish_reason=raw_record.get("finish_reason"),
            provider=raw_record.get("provider"), model=raw_record.get("model"), revision=raw_record.get("revision"),
            adapter_revision=raw_record.get("adapter_revision"), usage=usage,
            elapsed_seconds=raw_record.get("seconds"))
        result["receipt"] = asdict(receipt)
        if not result["identity_matches"]:
            result.update(status="MODEL_IDENTITY_MISMATCH", reason_code="raw_identity_differs_from_saved_run")
            return result
        if receipt.status != "CANDIDATE_UNREVIEWED":
            result.update(status="CANDIDATE_NOT_ELIGIBLE", reason_code=receipt.status)
            return result
        engine = MeaningExperienceEngine()
        checkpoint = engine.prepare_emlis_update(request, semantic_input=SemanticInput("FRESH_CANDIDATE", receipt=receipt,
            prior_snapshot_json=prior, semantic_profile=PROFILE))
        result.update(adoption="ADOPTED_PROVISIONAL", meaning_checkpoint=json_value(checkpoint),
                      semantic_snapshot=checkpoint.semantic_snapshot)
        resumed = replace(request, emlis_thread=replace(request.emlis_thread,
            prepared_meaning_checkpoint_ref=checkpoint.checkpoint_id))
        outcome = engine.generate(resumed, semantic_input=SemanticInput("RESUME_ADOPTED",
            snapshot_json=checkpoint.semantic_snapshot, semantic_profile=PROFILE))
        result["outcome"] = {"status": json_value(outcome.status), "reason_codes": list(outcome.reason_codes),
            "body_state": getattr(outcome, "body_state", None), "automatic_progression": outcome.automatic_progression,
            "question_decision": json_value(getattr(outcome, "question_decision", None))}
        result["question"] = json_value(getattr(outcome, "question", None))
        artifact = outcome.artifact
        if artifact is not None:
            result["body"] = {"artifact_id": artifact.artifact_id, "schema_version": artifact.schema_version,
                "observation": artifact.observation, "reception": artifact.reception,
                "update_note": getattr(artifact, "update_note", None), "text": artifact.text}
        result["status"] = "MEANING_AND_BODY_AVAILABLE" if artifact is not None else "MEANING_ADOPTED_BODY_UNAVAILABLE"
        return result
    except SemanticNotAdopted as exc:
        result.update(status="SEMANTIC_NOT_ADOPTED", decision=exc.decision, reason_code=exc.reason_code)
        return result
    except (ValueError, TypeError, KeyError, AttributeError, IndexError, UnicodeError) as exc:
        # Keep the original raw record; do not substitute a working packet or expose source-bearing exception text.
        result.update(status="CONSUMER_REJECTED", reason_code="consumer_" + type(exc).__name__)
        return result


def verify_stage(directory, run_directory, stage, *, expected_api_commit):
    examples, evaluation, manifest, data_hashes = validate_data(directory)
    report = strict_json((run_directory / "run.json").read_text(encoding="utf-8"))
    if (report.get("model"), report.get("revision"), report.get("semantic_profile")) != (MODEL, REVISION, PROFILE):
        raise ValueError("saved_run_model_identity_invalid")
    if (report.get("dataset_manifest_sha256") != digest(directory / "dataset_manifest.json")
            or report["preflight"].get("data_sha256") != data_hashes):
        raise ValueError("saved_run_dataset_differs_from_current_fixed_dataset")
    expected_adapter = None if stage == "before" else report["adapter_sha256"]["adapter_model.safetensors"]
    if stage == "after" and adapter_hashes(run_directory / "adapter") != report["adapter_sha256"]:
        raise ValueError("saved_after_adapter_hash_mismatch")
    by_case = {"FIT-" + row["id"]: row for row in examples}
    source = run_directory / (stage + ".jsonl")
    raw_rows = read_jsonl(source)
    rows, seen = [], set()
    for raw in raw_rows:
        case_id = raw.get("case_id")
        if case_id in seen:
            rows.append({"case_id": case_id, "status": "DUPLICATE_RAW_CASE_NOT_EVALUATED", "raw_record": raw})
        elif case_id not in FIT_IDS or case_id not in by_case:
            rows.append({"case_id": case_id, "status": "UNSUPPORTED_NOT_EVALUATED", "raw_record": raw,
                         "reason_code": "outside_chair_native_profile", "counted_as_semantic_success": False})
        else:
            rows.append(consume_raw(by_case[case_id], raw, expected_adapter_revision=expected_adapter))
        seen.add(case_id)
    expected_fit = FIT_IDS & set(by_case)
    missing = sorted(expected_fit - seen)
    result = {"schema": "cocolon.emlis_4b_fixed_raw_cmee_verification.v1", "scope": SCOPE,
        "stage": stage, "run_id": report["run_id"], "cmee_api_commit": expected_api_commit,
        "dataset_manifest_sha256": digest(directory / "dataset_manifest.json"), "source_raw_sha256": digest(source),
        "expected_adapter_revision": expected_adapter, "missing_fit_cases": missing, "cases": rows,
        "meaning_adopted_count": sum(x.get("adoption") == "ADOPTED_PROVISIONAL" for x in rows),
        "body_available_count": sum(x.get("status") == "MEANING_AND_BODY_AVAILABLE" for x in rows),
        "unsupported_count": sum(x.get("status") == "UNSUPPORTED_NOT_EVALUATED" for x in rows),
        "new_model_calls": 0, "database_operations": 0, "dynamic_thread_roundtrip": False,
        "service_saved_roundtrip": False, "product_accepted": False, "automatic_progression": False}
    write_json(run_directory / (stage + "_cmee.json"), result)
    return result


def main():
    parser = argparse.ArgumentParser()
    parser.add_argument("--directory", type=Path, default=Path(__file__).resolve().parent)
    parser.add_argument("--run-directory", type=Path, required=True)
    parser.add_argument("--api-root", type=Path, required=True)
    parser.add_argument("--stage", choices=["before", "after", "both"], default="both")
    args = parser.parse_args()
    directory, run_directory = args.directory.resolve(), args.run_directory.resolve()
    if run_directory.parent != directory / "results":
        raise ValueError("run_directory_outside_results")
    manifest = strict_json((directory / "dataset_manifest.json").read_text(encoding="utf-8"))
    commit = load_api(args.api_root, manifest.get("cmee_api_commit"))
    for stage in (["before", "after"] if args.stage == "both" else [args.stage]):
        result = verify_stage(directory, run_directory, stage, expected_api_commit=commit)
        print(json.dumps({k: result[k] for k in ("stage", "meaning_adopted_count", "body_available_count", "unsupported_count", "missing_fit_cases")}), flush=True)


if __name__ == "__main__":
    main()
